-- Published menu version 2 matches the owner's printed menu exactly.
-- Archive the old version; retain its rows and order-item references.
DO $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.site_content_releases WHERE release_id = 'vam-pizza-menu-v5')
 AND EXISTS (SELECT 1 FROM public.restaurants WHERE id = 'd4579042-8239-57df-b716-c27d3a6c213a') THEN
 IF (SELECT id FROM public.menu_versions WHERE restaurant_id = 'd4579042-8239-57df-b716-c27d3a6c213a' AND status = 'published') IS DISTINCT FROM 'db0d6a46-9145-55c7-af56-2795b510fa19'::uuid THEN
 RAISE EXCEPTION 'LOCAL_BOOTSTRAP_UNEXPECTED_MENU: manual publication needs review';
 END IF;
 UPDATE public.menu_versions SET status = 'archived',updated_at = now() WHERE id = 'db0d6a46-9145-55c7-af56-2795b510fa19';
 UPDATE public.menu_versions SET status = 'published',published_at = '2026-10-26 00:00:00+00',updated_at = now() WHERE id = 'd0d9081d-9d7e-5d65-93bd-7a46c4936866';
 UPDATE public.restaurants SET display_name = 'В.А.М. Пицца',updated_at = now() WHERE id = 'd4579042-8239-57df-b716-c27d3a6c213a';
 UPDATE public.site_branding SET display_name = 'В.А.М. Пицца',logo_alt = 'В.А.М. Пицца',localized_texts = (SELECT jsonb_agg(value || '{"displayName":"В.А.М. Пицца","shortName":"В.А.М. Пицца"}'::jsonb) FROM jsonb_array_elements(localized_texts)),seo_metadata = seo_metadata || '{"title":"В.А.М. Пицца — меню и заказ","description":"В.А.М. Пицца: пицца, роллы, бургеры и закуски"}'::jsonb,updated_at = now() WHERE singleton_id = 1;
 END IF;
END $$;
